/** One orb per project per domain it touches (Priceless Assets touches two). */
const ORBS = DOMAINS.flatMap((d, domain) =>
    PROJECTS.map((p, index) => ({ p, index, domain })).filter((x) => x.p.domains.includes(d.id))
).map((x, n, all) => ({
    ...x,
    slot: all.filter((y, m) => m < n && y.domain === x.domain).length,
    of: all.filter((y) => y.domain === x.domain).length,
    copy: x.p.domains.indexOf(DOMAINS[x.domain].id) > 0,
}));

