//#endregion

//#region Images

const LOGO_URLS = import.meta.glob<string>("../../assets/images/partners/*.webp", { eager: true, import: "default" });
// decoded off the main thread up front, so drawing them never stalls a frame
const LOGOS: Record<string, Picture | undefined> = {};
for (const [path, url] of Object.entries(LOGO_URLS)) {
    LOGOS[path.split("/").pop()!.replace(".webp", "")] = picture(url, 360);
}
const photo = (url?: string) => picture(url, 240);
const plain = (s: string) => s.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();

//#endregion

//#region Easing and drawing helpers

/** Springy overshoot, for things popping into place. */
const back = (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    const c1 = 1.9;
    return 1 + (c1 + 1) * Math.pow(x - 1, 3) + c1 * Math.pow(x - 1, 2);
};
const pop = (t: number, a: number, d = 0.55) => back(progress(t, a, a + d));
const hexA = (hex: string, a: number) => {
    const n = parseInt(hex.slice(1), 16);
    return `rgba(${n >> 16},${(n >> 8) & 255},${n & 255},${a})`;
};
const dot = (ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, Math.max(0, r), 0, Math.PI * 2);
    ctx.fill();
};
const line = (ctx: CanvasRenderingContext2D, x0: number, y0: number, x1: number, y1: number, f = 1) => {
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(lerp(x0, x1, f), lerp(y0, y1, f));
    ctx.stroke();
};
/** Scales everything drawn in `fn` around (x, y). */
const scaled = (ctx: CanvasRenderingContext2D, x: number, y: number, s: number, fn: () => void) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.translate(-x, -y);
    fn();
    ctx.restore();
};

/** Splits `value` into lines no wider than `maxWidth` at the current font. */
function wrap(ctx: CanvasRenderingContext2D, value: string, maxWidth: number) {
    const lines: string[] = [];
    let current = "";
    for (const word of value.split(" ")) {
        const next = current ? `${current} ${word}` : word;
        if (current && ctx.measureText(next).width > maxWidth) {
            lines.push(current);
            current = word;
        } else current = next;
    }
    if (current) lines.push(current);
    return lines;
}

/** A black pill with white capitals, like the city labels on Brightlands' map. */
function pill(ctx: CanvasRenderingContext2D, label: string, x: number, y: number, size: number, alpha: number, align: "left" | "right" | "center" = "left", fill = INK) {
    if (alpha <= 0.003) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.font = `700 ${size}px ${FONT}`;
    const w = ctx.measureText(label).width + size * 1.5;
    const h = size * 1.9;
    const x0 = align === "left" ? x : align === "right" ? x - w : x - w / 2;
    ctx.fillStyle = fill;
    ctx.beginPath();
    ctx.roundRect(x0, y - h / 2, w, h, h / 2);
    ctx.fill();
    text(ctx, label, x0 + w / 2, y + size * 0.04, size, { color: "#fff", weight: 700 });
    ctx.restore();
}

const ORG_NAMES: Record<string, string> = Object.fromEntries([...ABROAD, ...DUTCH, ...FUNDERS].map((o) => [o.id, o.name]));

/** A logo on its own, fitted into w × h, with a soft shadow; the name when there is no logo. */
function logo(ctx: CanvasRenderingContext2D, id: string, x: number, y: number, w: number, h: number, k: number, alpha: number) {
    if (alpha <= 0.003) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    const pic = LOGOS[id];
    const img = pic?.source;
    if (pic?.ready && img) {
        const s = Math.min(w / pic.width, h / pic.height);
        const iw = pic.width * s;
        const ih = pic.height * s;
        ctx.shadowColor = "rgba(11,16,32,0.22)";
        ctx.shadowBlur = 14 * k;
        ctx.shadowOffsetY = 4 * k;
        ctx.drawImage(img, x - iw / 2, y - ih / 2, iw, ih);
    } else {
        text(ctx, ORG_NAMES[id] ?? id, x, y, Math.min(h * 0.5, 26 * k), { color: INK, weight: 800, maxWidth: w });
    }
    ctx.restore();
}

/** A glossy coloured sphere. */
function orb(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, color: string, alpha: number) {
    if (alpha <= 0.003 || r <= 0.3) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.shadowColor = hexA(color, 0.45);
    ctx.shadowBlur = r * 1.2;
    const g = ctx.createRadialGradient(x - r * 0.35, y - r * 0.4, r * 0.1, x, y, r);
    g.addColorStop(0, "#fff");
    g.addColorStop(0.35, color);
    g.addColorStop(1, color);
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
}

/** Points along a gentle arc from (x0, y0) to (x1, y1), bowing upwards. */
function arcPoints(x0: number, y0: number, x1: number, y1: number, bow = 0.3) {
    const mx = (x0 + x1) / 2;
    const my = (y0 + y1) / 2;
    const d = Math.hypot(x1 - x0, y1 - y0);
    const nx = (y0 - y1) / (d || 1);
    const ny = (x1 - x0) / (d || 1);
    const flip = ny > 0 ? -1 : 1;
    const cx = mx + nx * d * bow * flip;
    const cy = my + ny * d * bow * flip;
    return (u: number) => ({
        x: (1 - u) * (1 - u) * x0 + 2 * (1 - u) * u * cx + u * u * x1,
        y: (1 - u) * (1 - u) * y0 + 2 * (1 - u) * u * cy + u * u * y1,
    });
}

/** A round portrait with a white ring; initials when there is no photo. */
function face(ctx: CanvasRenderingContext2D, url: string | undefined, name: string, x: number, y: number, r: number, k: number, alpha: number, ring = "#fff") {
    if (alpha <= 0.003 || r <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    ctx.shadowColor = "rgba(11,16,32,0.18)";
    ctx.shadowBlur = 10 * k;
    ctx.shadowOffsetY = 3 * k;
    dot(ctx, x, y, r + 3 * k, ring);
    ctx.shadowColor = "transparent";
    const pic = photo(url);
    const img = pic?.source;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.clip();
    if (pic?.ready && img) {
        const s = (2 * r) / Math.min(pic.width, pic.height);
        ctx.drawImage(img, x - (pic.width * s) / 2, y - (pic.height * s) / 2, pic.width * s, pic.height * s);
    } else {
        dot(ctx, x, y, r, "#e9ebf1");
        const initials = name
            .replace(/^((dr|prof|mr|ms|ir)\.?\s+)+/i, "")
            .split(" ")
            .map((w) => w[0])
            .join("")
            .slice(0, 2);
        text(ctx, initials, x, y, r * 0.7, { color: INK, weight: 700 });
    }
    ctx.restore();
}

/** A glyph sampled into a dot matrix, like the dotted Brightlands wordmark. */
const glyphs = new Map<string, { x: number; y: number }[]>();
function dottedGlyph(char: string, cells: number) {
    const key = `${char}${cells}`;
    const cached = glyphs.get(key);
    if (cached) return cached;
    const size = 200;
    const off = document.createElement("canvas");
    off.width = size;
    off.height = size;
    const c = off.getContext("2d")!;
    c.font = `900 ${size * 0.86}px ${FONT}`;
    c.textAlign = "center";
    c.textBaseline = "middle";
    c.fillText(char, size / 2, size / 2 + size * 0.04);
    const data = c.getImageData(0, 0, size, size).data;
    const step = size / cells;
    const dots: { x: number; y: number }[] = [];
    for (let y = step / 2; y < size; y += step)
        for (let x = step / 2; x < size; x += step)
            if (data[(Math.floor(y) * size + Math.floor(x)) * 4 + 3] > 140) dots.push({ x: x / size - 0.5, y: y / size - 0.5 });
    glyphs.set(key, dots);
    return dots;
}

/** A Brightlands campus disc: a colour gradient with a dotted "B". */
function campusDisc(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, from: string, to: string, alpha: number) {
    if (alpha <= 0.003 || r <= 0.5) return;
    ctx.save();
    ctx.globalAlpha *= alpha;
    const g = ctx.createLinearGradient(x - r, y - r, x + r, y + r);
    g.addColorStop(0, from);
    g.addColorStop(1, to);
    ctx.shadowColor = hexA(to, 0.35);
    ctx.shadowBlur = r * 0.6;
    dot(ctx, x, y, r, g as unknown as string);
    ctx.shadowColor = "transparent";
    ctx.fillStyle = "rgba(255,255,255,0.92)";
    const glyph = dottedGlyph("B", 11);
    const s = r * 1.15;
    for (const d of glyph) {
        ctx.beginPath();
        ctx.arc(x + d.x * s, y + d.y * s, Math.max(0.6, r * 0.035), 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.restore();
}

//#endregion

/** Decorative constellation behind everything, after Brightlands' map (illustrative). */
const STARS = (() => {
    const random = mulberry32(21);
    const pts = Array.from({ length: 26 }, () => ({ x: random(), y: random(), phase: random() * 6.28 }));
    const links: [number, number][] = [];
    pts.forEach((a, i) =>
        pts.forEach((b, j) => {
            if (j > i && Math.hypot(a.x - b.x, (a.y - b.y) * 0.6) < 0.16) links.push([i, j]);
        })
    );
    return { pts, links };
})();

const draw = ({ ctx, t, W, H, k, safe }: Frame) => {
    const span = safe.bottom - safe.top;
    const cy = safe.top + span / 2;

    //#region constellation backdrop
    {
        const p = (i: number) => {
            const s = STARS.pts[i];
            return { x: (s.x + Math.sin(t * 0.07 + s.phase) * 0.01) * W, y: (s.y + Math.cos(t * 0.06 + s.phase) * 0.012) * H };
        };
        ctx.save();
        ctx.strokeStyle = "rgba(230, 0, 60, 0.13)";
        ctx.lineWidth = 1;
        STARS.links.forEach(([a, b], n) => {
            const f = ease(progress(t, 0.3 + n * 0.05, 1.3 + n * 0.05));
            const A = p(a);
            const B = p(b);
            line(ctx, A.x, A.y, B.x, B.y, f);
        });
        STARS.pts.forEach((_, i) => {
            const A = p(i);
            ctx.globalAlpha = 0.35 + 0.25 * Math.sin(t * 1.3 + STARS.pts[i].phase);
            dot(ctx, A.x, A.y, 2.2 * k, PINK);
        });
        ctx.restore();
    }
    //#endregion

    /** Each scene arrives with a small zoom and leaves with a quick zoom-out, like a camera cut. */
    const camera = (a: number, b: number, fn: (enter: number) => void, { zoomIn = 0.06, zoomOut = 0.05 } = {}) => {
        if (t < a || t >= b) return;
        const enter = easeOut(progress(t, a, a + 0.5));
        const leave = ease(progress(t, b - 0.45, b));
        const s = 1 + zoomIn * (1 - enter) - zoomOut * leave;
        ctx.save();
        ctx.globalAlpha = Math.min(enter * 1.5, 1) * (1 - leave);
        scaled(ctx, W / 2, cy, s, () => fn(enter));
        ctx.restore();
    };

    //#region map: Limburg, the four campuses, then into Heerlen
    if (t >= T.map && t < T.team + 0.2) {
        const m = t - T.map;
        const COS = Math.cos((51 * Math.PI) / 180);
        const s0 = Math.min((span * 0.45) / 0.95, (W * 0.44) / (1.45 * COS));
        const zoom = ease(progress(m, 4.3, 5.9));
        const dive = Math.pow(progress(t, T.team - 0.8, T.team + 0.2), 2);
        const cam = {
            lon: lerp(5.55, HEERLEN.lon, zoom),
            lat: lerp(51.4, HEERLEN.lat, zoom),
            s: s0 * Math.exp(Math.log(3.3) * zoom + 2.2 * dive),
        };
        const P = (lon: number, lat: number) => ({ x: W / 2 + (lon - cam.lon) * COS * cam.s, y: cy + (cam.lat - lat) * cam.s });
        const mapAlpha = easeOut(progress(m, 0, 0.4)) * (1 - progress(t, T.team - 0.5, T.team + 0.1));
        const details = 1 - ease(progress(m, 4.0, 4.6)); // cities and capitals step back for the zoom

        ctx.save();
        ctx.globalAlpha = mapAlpha;
        ctx.beginPath();
        ctx.rect(0, safe.top, W, span);
        ctx.clip();

        // line-art map: coasts solid, borders dashed, drawn in
        const drawIn = ease(progress(m, 0.1, 1.6));
        const poly = (pts: number[], f: number) => {
            const n = Math.max(2, Math.floor((pts.length / 2) * f));
            ctx.beginPath();
            for (let i = 0; i < n; i++) {
                const q = P(pts[i * 2] / 100, pts[i * 2 + 1] / 100);
                if (i === 0) ctx.moveTo(q.x, q.y);
                else ctx.lineTo(q.x, q.y);
            }
        };
        const limburg = easeOut(progress(m, 0.8, 1.6));
        if (limburg > 0) {
            ctx.save();
            ctx.globalAlpha *= limburg;
            ctx.fillStyle = "#d6e8f6";
            GEO.limburg.forEach((pts) => {
                poly(pts, 1);
                ctx.closePath();
                ctx.fill();
            });
            ctx.restore();
        }
        ctx.strokeStyle = "rgba(11,16,32,0.75)";
        ctx.lineWidth = 1.4 * k;
        GEO.coast.forEach((pts) => {
            poly(pts, drawIn);
            ctx.stroke();
        });
        ctx.setLineDash([3 * k, 4 * k]);
        ctx.strokeStyle = "rgba(11,16,32,0.55)";
        GEO.border.forEach((pts) => {
            poly(pts, drawIn);
            ctx.stroke();
        });
        ctx.setLineDash([]);

        COUNTRY_LABELS.forEach((c, i) => {
            const q = P(c.lon, c.lat);
            text(ctx, c.id, q.x, q.y, 44 * k, { color: "rgba(11,16,32,0.35)", weight: 800, alpha: progress(m, 1 + i * 0.15, 1.5 + i * 0.15) * details });
        });

        // the 100 km around Heerlen
        const h = P(HEERLEN.lon, HEERLEN.lat);
        const radius = easeOut(progress(m, 2.6, 3.8));
        if (radius > 0) {
            const r = 0.8993 * cam.s;
            ctx.save();
            ctx.strokeStyle = "rgba(11,16,32,0.4)";
            ctx.lineWidth = 1.3 * k;
            ctx.setLineDash([2 * k, 5 * k]);
            ctx.beginPath();
            ctx.arc(h.x, h.y, r, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * radius);
            ctx.stroke();
            ctx.restore();
            const lx = h.x + Math.cos(-0.5) * r;
            const ly = h.y + Math.sin(-0.5) * r;
            text(ctx, "R = 100 km", lx + 12 * k, ly, 16 * k, { color: INK, weight: 600, align: "left", alpha: progress(m, 3.4, 3.8) * details });
        }

        // cities pop in, with thin pink links to Heerlen
        CITIES.forEach((c, i) => {
            const a = pop(m, 1.2 + i * 0.12);
            if (a <= 0) return;
            const q = P(c.lon, c.lat);
            ctx.save();
            ctx.strokeStyle = LINE_PINK;
            ctx.lineWidth = 1 * k;
            ctx.globalAlpha *= details;
            line(ctx, h.x, h.y, q.x, q.y, ease(progress(m, 2.2 + i * 0.08, 3.0 + i * 0.08)));
            ctx.strokeStyle = INK;
            ctx.lineWidth = 1.5 * k;
            ctx.beginPath();
            ctx.arc(q.x, q.y, 4.5 * k * (1 + 0.3 * Math.sin(t * 4 + i)), 0, Math.PI * 2);
            ctx.stroke();
            ctx.restore();
            scaled(ctx, q.x, q.y, a, () =>
                pill(ctx, c.name, q.x + c.side * 12 * k, q.y, 14 * k, Math.min(1, a) * details, c.side > 0 ? "left" : "right")
            );
        });

        // capitals, as outlined arrow boxes at the edges
        CAPITALS.forEach((c, i) => {
            const a = easeOut(progress(m, 2.0 + i * 0.2, 2.6 + i * 0.2)) * details;
            if (a <= 0.003) return;
            const x = c.at.x * W + (c.align === "left" ? -1 : 1) * (1 - a) * 60 * k;
            const y = safe.top + c.at.y * span;
            ctx.save();
            ctx.globalAlpha *= a;
            ctx.font = `600 ${20 * k}px ${FONT}`;
            const label = `${c.arrow}  ${c.name}`;
            const w = ctx.measureText(label).width + ctx.measureText(c.km).width * 0.8 + 40 * k;
            const bh = 44 * k;
            const x0 = c.align === "left" ? x : x - w;
            ctx.fillStyle = "#fff";
            ctx.strokeStyle = INK;
            ctx.lineWidth = 2 * k;
            ctx.beginPath();
            ctx.rect(x0, y - bh / 2, w, bh);
            ctx.fill();
            ctx.stroke();
            text(ctx, label, x0 + 14 * k, y, 20 * k, { color: INK, weight: 600, align: "left" });
            text(ctx, c.km, x0 + w - 12 * k, y + 1 * k, 15 * k, { color: INK, weight: 600, align: "right" });
            ctx.restore();
        });

        // the four campuses
        CAMPUSES.forEach((c, i) => {
            const a = pop(m, 1.9 + i * 0.22, 0.6);
            if (a <= 0) return;
            const q = P(c.lon, c.lat);
            const isBiss = c === HEERLEN;
            const r = (22 + (isBiss ? 22 : 8) * zoom) * k * a * (isBiss ? 1 + 1.6 * dive : 1);
            if (isBiss && zoom > 0) {
                // pulsing rings: this is where BISS sits
                for (let n = 0; n < 3; n++) {
                    const ph = (t * 0.7 + n / 3) % 1;
                    ctx.save();
                    ctx.globalAlpha *= zoom * (1 - ph) * 0.6;
                    ctx.strokeStyle = MAGENTA;
                    ctx.lineWidth = 2 * k;
                    ctx.beginPath();
                    ctx.arc(q.x, q.y, r * (1 + ph * 1.4), 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                }
            }
            campusDisc(ctx, q.x, q.y, r, c.from, c.to, Math.min(1, a));
            // campus names once zoomed in
            const label = progress(m, 5.2 + i * 0.1, 5.6 + i * 0.1) * (1 - dive * 3);
            if (!isBiss) pill(ctx, c.name, q.x + c.side * (r + 10 * k), q.y, 14 * k, label, c.side > 0 ? "left" : "right", "rgba(11,16,32,0.85)");
        });

        // BISS, at the Data & AI Campus
        const card = pop(m, 5.6, 0.6) * (1 - Math.min(1, dive * 3));
        if (card > 0) {
            const r = (22 + 22 * zoom) * k;
            const x = h.x + r + 22 * k;
            const y = h.y - r - 30 * k;
            scaled(ctx, x, y + 40 * k, card, () => {
                ctx.save();
                ctx.globalAlpha *= Math.min(1, card);
                ctx.shadowColor = "rgba(11,16,32,0.18)";
                ctx.shadowBlur = 20 * k;
                ctx.shadowOffsetY = 6 * k;
                ctx.fillStyle = "#fff";
                const w = Math.min(430 * k, W - x - 20 * k);
                ctx.beginPath();
                ctx.roundRect(x, y - 44 * k, w, 92 * k, 12 * k);
                ctx.fill();
                ctx.shadowColor = "transparent";
                const g = ctx.createLinearGradient(x, 0, x + w, 0);
                g.addColorStop(0, CYAN);
                g.addColorStop(1, MAGENTA);
                ctx.fillStyle = g;
                ctx.fillRect(x, y - 44 * k, 6 * k, 92 * k);
                text(ctx, "BISS", x + 24 * k, y - 14 * k, 30 * k, { color: INK, weight: 800, align: "left" });
                text(ctx, `${CAMPUS_NAME}, Heerlen`, x + 24 * k, y + 22 * k, 17 * k, {
                    color: GREY,
                    weight: 600,
                    align: "left",
                    maxWidth: w - 40 * k,
                });
                ctx.restore();
            });
        }
        ctx.restore();

        // soft edges where the map meets the title and caption areas
        const fade = (y0: number, y1: number) => {
            const g = ctx.createLinearGradient(0, y0, 0, y1);
            g.addColorStop(0, "rgba(255,255,255,1)");
            g.addColorStop(1, "rgba(255,255,255,0)");
            ctx.fillStyle = g;
            ctx.fillRect(0, Math.min(y0, y1), W, Math.abs(y1 - y0));
        };
        fade(safe.top, safe.top + 40 * k);
        fade(safe.bottom, safe.bottom - 40 * k);
    }
    //#endregion

    //#region team: everyone flies in around BISS
    const people = props.members;
    camera(T.team, T.decade, () => {
        const m = t - T.team;
        const n = Math.max(1, people.length);
        const outer = span * 0.43;
        const c = outer / Math.sqrt(n + 2.6);
        const fr = Math.min(c * 0.78, 52 * k);
        const spin = m * 0.06;
        const hubR = c * 1.25;

        // discipline tags with pink links to the team (links first, under everything)
        const tags = DISCIPLINES.map((label, i) => {
            const right = i < 3;
            const row = i % 3;
            const angle = (right ? 0 : Math.PI) + (row - 1) * 0.55 * (right ? 1 : -1);
            const x = W / 2 + Math.cos(angle) * (outer + 70 * k) + (right ? 1 : -1) * 10 * k;
            const y = cy + Math.sin(angle) * outer * 0.95;
            return { label, x, y, right, color: DISCIPLINE_COLORS[i], at: 2.4 + i * 0.18 };
        });
        tags.forEach((g) => {
            const f = ease(progress(m, g.at, g.at + 0.5));
            if (f <= 0) return;
            ctx.save();
            ctx.strokeStyle = hexA(g.color, 0.5);
            ctx.lineWidth = 1.5 * k;
            line(ctx, g.x, g.y, W / 2, cy, f * 0.75);
            ctx.restore();
        });

        // hub
        const hub = pop(m, 0.05, 0.6);
        campusDisc(ctx, W / 2, cy, hubR * hub, CYAN, MAGENTA, Math.min(1, hub));

        // faces: phyllotaxis, flying in from all sides
        const random = mulberry32(5);
        people.forEach((p, i) => {
            const from = (random() - 0.5) * 1.1 + (i % 2 ? Math.PI : 0);
            const arrive = 0.3 + i * 0.06;
            const f = back(progress(m, arrive, arrive + 0.75));
            const leave = ease(progress(t, T.decade - 0.9 + (i % 7) * 0.03, T.decade - 0.4));
            if (f <= 0) return;
            const angle = i * 2.39996 + spin;
            const r = c * Math.sqrt(i + 2.6);
            const hx = W / 2 + Math.cos(angle) * r * 1.12;
            const hy = cy + Math.sin(angle) * r;
            const sx = W / 2 + Math.cos(from) * W * 0.7;
            const sy = cy + Math.sin(from) * H * 0.7;
            const x = lerp(lerp(sx, hx, f), W / 2, leave);
            const y = lerp(lerp(sy, hy, f), cy, leave);
            face(ctx, p.photo, p.title, x, y, fr * (0.6 + 0.4 * Math.min(f, 1)) * (1 - leave * 0.7), k, Math.min(1, f * 2) * (1 - leave));
        });

        // the count, in the hub
        const count = Math.round(people.length * ease(progress(m, 0.4, 0.4 + people.length * 0.06)));
        if (hub > 0.5 && people.length) {
            ctx.save();
            ctx.globalAlpha *= progress(m, 0.6, 1);
            dot(ctx, W / 2, cy, hubR * 0.62, "#fff");
            ctx.restore();
            text(ctx, String(count), W / 2, cy - hubR * 0.08, hubR * 0.5, { color: INK, weight: 800, alpha: progress(m, 0.6, 1) });
            text(ctx, "people", W / 2, cy + hubR * 0.32, hubR * 0.17, { color: GREY, weight: 700, alpha: progress(m, 0.6, 1) });
        }

        tags.forEach((g) => {
            const a = pop(m, g.at + 0.2);
            if (a <= 0) return;
            ctx.font = `700 ${22 * k}px ${FONT}`;
            const w = ctx.measureText(g.label).width + 50 * k;
            const room = g.right ? W - g.x - 12 * k : g.x - 12 * k;
            const scale = Math.min(1, room / w);
            const cx = g.right ? g.x + (w * scale) / 2 : g.x - (w * scale) / 2;
            scaled(ctx, cx, g.y, a * scale, () => {
                ctx.save();
                ctx.globalAlpha *= Math.min(1, a);
                ctx.shadowColor = "rgba(11,16,32,0.12)";
                ctx.shadowBlur = 14 * k;
                ctx.fillStyle = "#fff";
                ctx.beginPath();
                ctx.roundRect(cx - w / 2, g.y - 22 * k, w, 44 * k, 22 * k);
                ctx.fill();
                ctx.shadowColor = "transparent";
                dot(ctx, cx - w / 2 + 20 * k, g.y, 6 * k, g.color);
                text(ctx, g.label, cx - w / 2 + 34 * k, g.y + 1 * k, 22 * k, { color: INK, weight: 700, align: "left" });
                ctx.restore();
            });
        });
    });
    //#endregion

    //#region decade: the timeline sweeps, projects pop up as a constellation, the numbers land
    const orbR = Math.max(7, 13 * k);
    const starAt = (i: number) => ({
        x: W * 0.1 + (i % 7) * ((W * 0.8) / 6),
        y: safe.top + span * (i < 7 ? 0.44 : 0.62) + Math.sin(i * 2.1) * span * 0.025,
    });
    const popAt = (i: number) => T.decade + 0.9 + i * 0.13;

    camera(
        T.decade,
        T.domains,
        () => {
            const m = t - T.decade;
            ctx.save();
            ctx.translate((1 - back(progress(m, 0, 0.8))) * W * 0.25, 0);
            const x0 = W * 0.08;
            const x1 = W * 0.92;
            const y = safe.top + span * 0.15;
            const xOf = (year: number) => lerp(x0, x1, (year - 2016) / 10);
            const head = ease(progress(m, 0.3, 2.6));
            const hx = lerp(x0, x1, head);
            ctx.save();
            ctx.strokeStyle = HAIR;
            ctx.lineWidth = 4 * k;
            line(ctx, x0, y, x1, y);
            const g = ctx.createLinearGradient(x0, 0, x1, 0);
            g.addColorStop(0, MAGENTA);
            g.addColorStop(1, PINK);
            ctx.strokeStyle = g;
            line(ctx, x0, y, hx, y);
            for (let year = 2016; year <= 2026; year++) dot(ctx, xOf(year), y, 4 * k, hx >= xOf(year) - 2 ? INK : HAIR);
            if (head < 1) dot(ctx, hx, y, 9 * k, PINK);
            ctx.restore();
            text(ctx, "2016", x0 - 14 * k, y, 18 * k, { color: INK, weight: 800, align: "right" });
            text(ctx, "2026", x1 + 14 * k, y, 18 * k, { color: INK, weight: 800, align: "left", alpha: progress(head, 0.95, 1) });
            MILESTONES.forEach((ms) => {
                const x = xOf(ms.year);
                const a = pop(hx, x - 100 * k, 100 * k);
                if (a <= 0) return;
                const dir = ms.up ? -1 : 1;
                ctx.save();
                ctx.strokeStyle = ms.color;
                ctx.lineWidth = 2 * k;
                line(ctx, x, y + dir * 10 * k, x, y + dir * 26 * k, Math.min(1, a));
                ctx.restore();
                dot(ctx, x, y, 10 * k * Math.min(1.2, a), ms.color);
                dot(ctx, x, y, 4 * k, "#fff");
                const align: CanvasTextAlign = x > W * 0.75 ? "right" : "left";
                const tx = x + (align === "left" ? -6 : 6) * k;
                const ty = ms.up ? y - 64 * k : y + 44 * k;
                scaled(ctx, tx, ty, 0.85 + 0.15 * a, () => {
                    text(ctx, ms.title, tx, ty, 22 * k, { color: INK, weight: 800, align, alpha: Math.min(1, a) });
                    text(ctx, ms.sub, tx, ty + 24 * k, 15 * k, { color: GREY, weight: 600, align, alpha: Math.min(1, a), maxWidth: W * 0.3 });
                });
            });
            ctx.restore();

            // pink constellation lines between neighbouring projects, under the orbs
            ctx.save();
            ctx.strokeStyle = LINE_PINK;
            ctx.lineWidth = 1.3 * k;
            PROJECTS.forEach((_, i) => {
                const a = starAt(i);
                const next = [i % 7 < 6 ? i + 1 : -1, i < 7 ? i + 7 : -1].filter((j) => j >= 0);
                next.forEach((j) => {
                    const b = starAt(j);
                    line(ctx, a.x, a.y, b.x, b.y, ease(progress(t, popAt(Math.max(i, j)), popAt(Math.max(i, j)) + 0.5)));
                });
            });
            ctx.restore();

            // BISS in numbers: big and bold
            const sy = safe.top + span * 0.86;
            STATS.forEach((s, i) => {
                const x = W * (0.25 + i * 0.25);
                const a = pop(m, 3.0 + i * 0.25, 0.7);
                if (a <= 0) return;
                const v = Math.round(s.value * ease(progress(m, 3.0 + i * 0.25, 4.4 + i * 0.25)));
                scaled(ctx, x, sy, Math.max(0, a), () => {
                    text(ctx, String(v), x, sy - 12 * k, 66 * k, { color: [MAGENTA, PINK, ORANGE][i], weight: 900 });
                    text(ctx, s.label.toUpperCase(), x, sy + 34 * k, 17 * k, { color: INK, weight: 800 });
                });
            });
        },
        { zoomIn: 0, zoomOut: 0.02 }
    );
    //#endregion

    //#region domains: the orbs fly into six coloured rings
    const ringR = Math.min(span * 0.11, W * 0.05);
    const cellX = (d: number) => W * (0.04 + 0.32 * (d % 3));
    const cellY = (d: number) => safe.top + Math.floor(d / 3) * (span / 2);
    const ringAt = (d: number) => ({ x: cellX(d) + ringR + 12 * k, y: cellY(d) + span * 0.28 });
    const flyAt = (o: (typeof ORBS)[number]) => T.domains + 0.45 + o.index * 0.1 + (o.copy ? 0.25 : 0);
    const domainLeave = ease(progress(t, T.how - 0.45, T.how));

    if (t >= T.domains && t < T.how) {
        DOMAINS.forEach((d, i) => {
            const first = Math.min(...ORBS.filter((o) => o.domain === i).map(flyAt));
            const a = pop(t, first + 0.35, 0.6);
            if (a <= 0) return;
            const c = ringAt(i);
            const count = ORBS.filter((o) => o.domain === i).length;
            ctx.save();
            ctx.globalAlpha *= 1 - domainLeave;
            scaled(ctx, c.x, c.y, Math.max(0, a), () => {
                ctx.save();
                ctx.globalAlpha *= 0.13;
                dot(ctx, c.x, c.y, ringR, d.color);
                ctx.restore();
                ctx.strokeStyle = d.color;
                ctx.lineWidth = 3 * k;
                ctx.beginPath();
                ctx.arc(c.x, c.y, ringR, 0, Math.PI * 2);
                ctx.stroke();
                text(ctx, String(count), c.x, c.y + 2 * k, ringR * 0.8, { color: d.color, weight: 900 });
            });
            text(ctx, d.label, cellX(i), cellY(i) + span * 0.08, 26 * k, {
                color: INK,
                weight: 800,
                align: "left",
                alpha: Math.min(1, Math.max(0, a)),
                maxWidth: W * 0.29,
            });
            ctx.restore();
        });
    }

    // the orbs themselves, from the constellation to their rings
    if (t >= T.decade && t < T.how) {
        const decadeLeave = ease(progress(t, T.domains - 0.45, T.domains));
        ORBS.forEach((o) => {
            const a = back(progress(t, popAt(o.index), popAt(o.index) + 0.5));
            if (a <= 0) return;
            const fly = ease(progress(t, flyAt(o), flyAt(o) + 0.85));
            const from = starAt(o.index);
            const c = ringAt(o.domain);
            const angle = (o.of === 1 ? 0 : lerp(-0.95, 0.95, o.slot / (o.of - 1))) + Math.sin(t * 0.9 + o.domain) * 0.05;
            const to = { x: c.x + Math.cos(angle) * ringR, y: c.y + Math.sin(angle) * ringR };
            const x = lerp(from.x, to.x, fly);
            const y = lerp(from.y, to.y, fly) - Math.sin(fly * Math.PI) * 70 * k;
            const alpha = (o.copy ? progress(fly, 0, 0.15) : 1) * (1 - domainLeave);
            const color = DOMAINS[o.domain].color;
            orb(ctx, x, y, orbR * Math.max(0, a) * (1 + 0.25 * Math.sin(fly * Math.PI)), o.copy ? color : domainColor(o.p), alpha * Math.min(1, a));
            // label under the orb in the constellation, beside it on the ring
            if (!o.copy)
                text(ctx, o.p.title, from.x, from.y + orbR + 18 * k, 16 * k, {
                    color: INK,
                    weight: 700,
                    alpha: Math.min(1, a) * (1 - progress(fly, 0, 0.2)) * (1 - decadeLeave * (fly > 0 ? 0 : 1)),
                    maxWidth: (W * 0.8) / 6 - 12 * k,
                });
            const lx = to.x + orbR + 10 * k;
            text(ctx, o.p.title, lx, to.y, 18 * k, {
                color: INK,
                weight: 700,
                align: "left",
                alpha: progress(fly, 0.85, 1) * (1 - domainLeave),
                maxWidth: cellX(o.domain) + W * 0.3 - lx,
            });
        });
    }
    //#endregion

    //#region how: one project travels a single path; each station blooms, then makes way
    camera(T.how, T.partners, () => {
        const m = t - T.how;
        const x0 = W * 0.1;
        const x1 = W * 0.9;
        const base = safe.top + span * 0.22;
        const amp = span * 0.07;
        const at = (u: number) => ({ x: lerp(x0, x1, u), y: base + Math.sin(u * Math.PI * 2) * amp });
        const arrive = (i: number) => 0.4 + i * 1.75;
        const pos = STATIONS.reduce((sum, _, i) => sum + (i === 0 ? 0 : back(progress(m, arrive(i) - 0.65, arrive(i)))), 0);
        const u = Math.min(1, Math.max(0, pos / (STATIONS.length - 1)));

        // the path: faint all the way, coloured up to the project
        const drawPath = (to: number) => {
            ctx.beginPath();
            for (let n = 0; n <= 80 * to; n++) {
                const q = at(n / 80);
                if (n === 0) ctx.moveTo(q.x, q.y);
                else ctx.lineTo(q.x, q.y);
            }
            ctx.stroke();
        };
        ctx.save();
        ctx.lineCap = "round";
        ctx.strokeStyle = HAIR;
        ctx.lineWidth = 5 * k;
        drawPath(ease(progress(m, 0, 0.6)));
        const g = ctx.createLinearGradient(x0, 0, x1, 0);
        STATIONS.forEach((s, i) => g.addColorStop(i / (STATIONS.length - 1), s.color));
        ctx.strokeStyle = g;
        drawPath(u);
        ctx.restore();

        STATIONS.forEach((s, i) => {
            const q = at(i / (STATIONS.length - 1));
            const a = pop(m, 0.1 + i * 0.12);
            const lit = progress(m, arrive(i) - 0.1, arrive(i) + 0.2);
            scaled(ctx, q.x, q.y, Math.max(0, a) * (1 + 0.25 * lit * (1 - progress(m, arrive(i) + 0.2, arrive(i) + 0.6))), () => {
                dot(ctx, q.x, q.y, 20 * k, lit > 0 ? s.color : "#fff");
                ctx.strokeStyle = s.color;
                ctx.lineWidth = 3 * k;
                ctx.beginPath();
                ctx.arc(q.x, q.y, 20 * k, 0, Math.PI * 2);
                ctx.stroke();
            });
            text(ctx, s.label, q.x, q.y + 42 * k, 22 * k, { color: INK, weight: 800, alpha: Math.min(1, Math.max(0, a)) });
        });

        // the project, with a short trail
        const p = at(u);
        for (let j = 6; j >= 1; j--) {
            const tq = at(Math.max(0, u - j * 0.012));
            ctx.save();
            ctx.globalAlpha *= 0.12 * (7 - j) * progress(m, 0.3, 0.6);
            dot(ctx, tq.x, tq.y, (9 - j) * k, INK);
            ctx.restore();
        }
        const ta = pop(m, 0.25);
        if (ta > 0) {
            dot(ctx, p.x, p.y, 11 * k * ta, INK);
            dot(ctx, p.x, p.y, 4.5 * k * ta, "#fff");
            ctx.font = `800 ${16 * k}px ${FONT}`;
            const label = "Clear welfare application";
            const w = ctx.measureText(label).width + 30 * k;
            const lx = Math.min(Math.max(p.x, w / 2 + 12 * k), W - w / 2 - 12 * k);
            const ly = p.y - 40 * k;
            scaled(ctx, lx, ly, Math.max(0, ta), () => {
                ctx.fillStyle = INK;
                ctx.beginPath();
                ctx.roundRect(lx - w / 2, ly - 16 * k, w, 32 * k, 16 * k);
                ctx.fill();
                text(ctx, label, lx, ly + 1 * k, 16 * k, { color: "#fff", weight: 800 });
            });
        }

        // what happens at each station blooms below it, then makes way for the next
        const top = base + amp + 70 * k;
        const bottom = safe.bottom - 8 * k;
        const vh = (bottom - top) * 0.46;
        STATIONS.forEach((s, i) => {
            const inA = back(progress(m, arrive(i) + 0.05, arrive(i) + 0.55));
            const out = i < STATIONS.length - 1 ? ease(progress(m, arrive(i + 1) - 0.6, arrive(i + 1) - 0.25)) : 0;
            if (inA <= 0 || out >= 1) return;
            const alpha = Math.min(1, inA) * (1 - out);
            const sx = at(i / (STATIONS.length - 1)).x;
            const cx = Math.min(Math.max(sx, W * 0.27), W * 0.73);
            const vy = top + vh / 2;
            ctx.save();
            ctx.globalAlpha *= alpha;
            // a thin guide from the station down to its content
            ctx.strokeStyle = hexA(s.color, 0.5);
            ctx.lineWidth = 2 * k;
            ctx.setLineDash([3 * k, 5 * k]);
            line(ctx, sx, at(i / (STATIONS.length - 1)).y + 58 * k, cx, top - 6 * k);
            ctx.setLineDash([]);
            scaled(ctx, cx, vy, 0.85 + 0.15 * Math.max(0, inA) - out * 0.08, () => {
                if (i === 0) logo(ctx, "gemeente-sittard-geleen", cx, vy, Math.min(W * 0.32, 460 * k), vh * 0.75, k, 1);
                if (i === 1) {
                    const team = EXAMPLE_TEAM.map((n) => props.members.find((pp) => plain(pp.title).includes(n)));
                    const fr = Math.min(vh * 0.33, 58 * k);
                    team.forEach((pp, j) => {
                        const fa = back(progress(m, arrive(1) + 0.15 + j * 0.1, arrive(1) + 0.6 + j * 0.1));
                        const fx = cx + (j - 1.5) * fr * 2.9;
                        const name = (pp?.title ?? "").replace(/^((dr|prof|mr|ms|ir)\.?\s+)+/i, "");
                        face(ctx, pp?.photo, pp?.title ?? EXAMPLE_TEAM[j], fx, vy - vh * 0.1, fr * Math.max(0, fa), k, Math.min(1, Math.max(0, fa)));
                        text(ctx, name, fx, vy - vh * 0.1 + fr + 18 * k, 15 * k, { color: INK, weight: 700, alpha: Math.min(1, Math.max(0, fa)), maxWidth: fr * 2.7 });
                    });
                }
                if (i === 2) {
                    // an illustrative sketch of a simpler application form, drawing itself
                    const fh = vh * 0.95;
                    const fw = fh * 0.62;
                    const d = ease(progress(m, arrive(2) + 0.1, arrive(2) + 0.7));
                    ctx.strokeStyle = INK;
                    ctx.lineWidth = 2.5 * k;
                    ctx.beginPath();
                    ctx.roundRect(cx - fw / 2, vy - fh / 2, fw, fh * d, 14 * k);
                    ctx.stroke();
                    for (let j = 0; j < 3; j++) {
                        const ry = vy - fh * 0.25 + j * fh * 0.2;
                        const done = progress(m, arrive(2) + 0.6 + j * 0.25, arrive(2) + 0.8 + j * 0.25);
                        ctx.strokeStyle = HAIR;
                        ctx.lineWidth = 8 * k;
                        ctx.lineCap = "round";
                        line(ctx, cx - fw * 0.18, ry, cx + fw * 0.32, ry, d);
                        ctx.lineCap = "butt";
                        dot(ctx, cx - fw * 0.32, ry, 9 * k * d, done > 0 ? CYAN : HAIR);
                        if (done > 0) {
                            ctx.strokeStyle = "#fff";
                            ctx.lineWidth = 2.4 * k;
                            ctx.beginPath();
                            ctx.moveTo(cx - fw * 0.32 - 5 * k, ry);
                            ctx.lineTo(cx - fw * 0.32 - 1 * k, ry + 4 * k);
                            ctx.lineTo(cx - fw * 0.32 + 5 * k, ry - 4 * k);
                            ctx.stroke();
                        }
                    }
                    const btn = progress(m, arrive(2) + 1.2, arrive(2) + 1.4);
                    ctx.fillStyle = hexA(CYAN, btn);
                    ctx.beginPath();
                    ctx.roundRect(cx - fw * 0.3, vy + fh * 0.32, fw * 0.6, fh * 0.1, fh * 0.05);
                    ctx.fill();
                }
            });
            // the words
            if (i === 3) {
                ctx.font = `italic 700 ${30 * k}px ${FONT}`;
                const lines = wrap(ctx, QUOTE, Math.min(W * 0.62, 900 * k));
                const lh = 40 * k;
                const y0 = top + (bottom - top) / 2 - ((lines.length + 1) * lh) / 2;
                ctx.fillStyle = INK;
                ctx.textAlign = "center";
                ctx.textBaseline = "middle";
                lines.forEach((l, j) => ctx.fillText(l, cx, y0 + j * lh + lh / 2));
                text(ctx, "Municipality of Sittard-Geleen", cx, y0 + lines.length * lh + lh * 0.6, 18 * k, { color: GREEN, weight: 800 });
            } else {
                ctx.font = `500 ${22 * k}px ${FONT}`;
                const lines = wrap(ctx, s.body, Math.min(W * 0.42, 620 * k));
                lines.forEach((l, j) => text(ctx, l, cx, top + vh + 26 * k + j * 30 * k, 22 * k, { color: "#1f2937", weight: 500 }));
            }
            ctx.restore();
        });
    });
    //#endregion

    //#region partners: a map of Europe, arcs out from BISS, then into the Netherlands; funders rise
    camera(T.partners, T.outro, () => {
        // the scene was paced for 7.5 s; play it at 60% speed so the logos have time to land
        const m = (t - T.partners) * 0.6;
        const COS = Math.cos((51 * Math.PI) / 180);
        const sEu = Math.min((span * 0.93) / 15.4, (W * 0.9) / (22 * COS));
        const sNl = Math.min((span * 0.92) / 2.75, (W * 0.5) / (3.6 * COS));
        const zoom = ease(progress(m, 2.9, 3.9));
        const intro = easeOut(progress(m, 0, 0.9));
        const cam = {
            lon: lerp(lerp(5.6, 4.6, intro), 5.25, zoom),
            lat: lerp(lerp(50.2, 46.6, intro), 52.0, zoom),
            s: Math.exp(lerp(Math.log(sEu * lerp(2.2, 1, intro)), Math.log(sNl), zoom)),
        };
        const P = (lon: number, lat: number) => ({ x: W / 2 + (lon - cam.lon) * COS * cam.s, y: cy + (cam.lat - lat) * cam.s });
        const H = P(HEERLEN.lon, HEERLEN.lat);
        const funders = progress(m, 5.5, 6.1);
        const dim = 1 - 0.8 * funders;

        ctx.save();
        ctx.beginPath();
        ctx.rect(0, safe.top, W, span);
        ctx.clip();
        ctx.globalAlpha *= dim;
        const lines = (geo: number[][], dashed: boolean, alpha: number) => {
            if (alpha <= 0.003) return;
            ctx.save();
            ctx.globalAlpha *= alpha;
            ctx.strokeStyle = dashed ? "rgba(11,16,32,0.45)" : "rgba(11,16,32,0.7)";
            ctx.lineWidth = 1.3 * k;
            ctx.setLineDash(dashed ? [3 * k, 4 * k] : []);
            geo.forEach((pts) => {
                ctx.beginPath();
                for (let n = 0; n < pts.length / 2; n++) {
                    const q = P(pts[n * 2] / 100, pts[n * 2 + 1] / 100);
                    if (n === 0) ctx.moveTo(q.x, q.y);
                    else ctx.lineTo(q.x, q.y);
                }
                ctx.stroke();
            });
            ctx.restore();
        };
        const eu = 1 - progress(zoom, 0.5, 0.9);
        const nl = progress(zoom, 0.4, 0.9);
        if (nl > 0) {
            ctx.save();
            ctx.globalAlpha *= nl;
            ctx.fillStyle = "#d6e8f6";
            GEO.limburg.forEach((pts) => {
                ctx.beginPath();
                for (let n = 0; n < pts.length / 2; n++) {
                    const q = P(pts[n * 2] / 100, pts[n * 2 + 1] / 100);
                    if (n === 0) ctx.moveTo(q.x, q.y);
                    else ctx.lineTo(q.x, q.y);
                }
                ctx.fill();
            });
            ctx.restore();
        }
        lines(EUROPE.coast, false, eu);
        lines(EUROPE.border, true, eu);
        lines(GEO.coast, false, nl);
        lines(GEO.border, true, nl);

        // arcs out from BISS (drawn first: under every logo)
        const arc = (q: { x: number; y: number }, start: number, alpha: number, bow = 0.28) => {
            const f = ease(progress(m, start, start + 0.5));
            if (f <= 0 || alpha <= 0.003) return;
            const pt = arcPoints(H.x, H.y, q.x, q.y, bow);
            ctx.save();
            ctx.globalAlpha *= alpha;
            ctx.strokeStyle = "rgba(230, 0, 60, 0.55)";
            ctx.lineWidth = 2 * k;
            ctx.beginPath();
            for (let n = 0; n <= 30 * f; n++) {
                const a = pt(n / 30);
                if (n === 0) ctx.moveTo(a.x, a.y);
                else ctx.lineTo(a.x, a.y);
            }
            ctx.stroke();
            const head = pt(f);
            if (f < 1) dot(ctx, head.x, head.y, 5 * k, PINK);
            else {
                // landing ripple
                const r = progress(m, start + 0.5, start + 1.1);
                ctx.strokeStyle = hexA(PINK, 1 - r);
                ctx.lineWidth = 2 * k;
                ctx.beginPath();
                ctx.arc(q.x, q.y, 6 * k + r * 22 * k, 0, Math.PI * 2);
                ctx.stroke();
                dot(ctx, q.x, q.y, 4.5 * k, PINK);
            }
            ctx.restore();
        };
        const abroadAt = (j: number) => 0.6 + j * 0.26;
        const abroadAlpha = 1 - progress(zoom, 0, 0.35);
        ABROAD.forEach((o, j) => arc(P(o.lon, o.lat), abroadAt(j), abroadAlpha));

        // Dutch partners: two columns of logos either side of the country, with leaders to their pins
        const dutchAt = (j: number) => 3.75 + j * 0.09;
        const left = DUTCH.filter((o) => o.lon < 5.3).sort((a, b) => b.lat - a.lat);
        const right = DUTCH.filter((o) => o.lon >= 5.3).sort((a, b) => b.lat - a.lat);
        const lw = Math.min(W * 0.15, 200 * k);
        const slotH = (span * 0.9) / Math.max(left.length, right.length);
        const lh = Math.min(slotH * 0.72, 56 * k);
        const slot = (o: Org) => {
            const col = left.includes(o) ? left : right;
            const n = col.indexOf(o);
            return {
                x: col === left ? W * 0.13 : W * 0.87,
                y: safe.top + span * 0.05 + (n + 0.5) * ((span * 0.9) / col.length),
                side: col === left ? 1 : -1,
            };
        };
        DUTCH.forEach((o, j) => {
            const q = P(o.lon, o.lat);
            arc(q, dutchAt(j), nl, 0.18);
            const sl = slot(o);
            const f = ease(progress(m, dutchAt(j) + 0.35, dutchAt(j) + 0.7));
            if (f <= 0) return;
            ctx.save();
            ctx.globalAlpha *= nl;
            ctx.strokeStyle = "rgba(11,16,32,0.25)";
            ctx.lineWidth = 1.2 * k;
            line(ctx, q.x, q.y, sl.x + (sl.side * lw) / 2 + sl.side * 10 * k, sl.y, f);
            ctx.restore();
        });

        // BISS at Heerlen
        campusDisc(ctx, H.x, H.y, (14 + 8 * zoom) * k * pop(m, 0.2), HEERLEN.from, HEERLEN.to, 1);

        // logos: abroad pop at their pins, Dutch ones into their slots
        ABROAD.forEach((o, j) => {
            const q = P(o.lon, o.lat);
            const a = back(progress(m, abroadAt(j) + 0.45, abroadAt(j) + 0.95));
            if (a <= 0) return;
            const x = q.x + (o.dx ?? 0) * k;
            const y = q.y + (o.dy ?? 0) * k;
            ctx.save();
            ctx.globalAlpha *= abroadAlpha;
            ctx.strokeStyle = "rgba(11,16,32,0.3)";
            ctx.lineWidth = 1.2 * k;
            line(ctx, q.x, q.y, x, y + 22 * k, Math.min(1, a));
            ctx.restore();
            scaled(ctx, x, y, Math.max(0, a), () => logo(ctx, o.id, x, y, 170 * k, 58 * k, k, Math.min(1, a) * abroadAlpha));
        });
        DUTCH.forEach((o, j) => {
            const sl = slot(o);
            const a = back(progress(m, dutchAt(j) + 0.45, dutchAt(j) + 0.9));
            if (a <= 0) return;
            scaled(ctx, sl.x, sl.y, Math.max(0, a), () => logo(ctx, o.id, sl.x, sl.y, lw, lh, k, Math.min(1, a) * nl));
        });
        text(ctx, "EUROPE", W * 0.04, safe.top + 18 * k, 16 * k, { color: GREY, weight: 800, align: "left", alpha: abroadAlpha * progress(m, 0.6, 1) });
        ctx.restore();

        // soft edges into the title and caption areas
        const fade = (y0: number, y1: number) => {
            const gg = ctx.createLinearGradient(0, y0, 0, y1);
            gg.addColorStop(0, "rgba(255,255,255,1)");
            gg.addColorStop(1, "rgba(255,255,255,0)");
            ctx.fillStyle = gg;
            ctx.fillRect(0, Math.min(y0, y1), W, Math.abs(y1 - y0));
        };
        fade(safe.top, safe.top + 30 * k);
        fade(safe.bottom, safe.bottom - 30 * k);

        // the funders rise as one bold band
        if (funders > 0) {
            const rise = back(progress(m, 5.5, 6.2));
            const bh = Math.min(span * 0.3, 210 * k);
            const by = lerp(safe.bottom + bh, cy, rise);
            ctx.save();
            ctx.shadowColor = "rgba(11,16,32,0.18)";
            ctx.shadowBlur = 40 * k;
            ctx.fillStyle = "#fff";
            ctx.fillRect(0, by - bh / 2, W, bh);
            ctx.shadowColor = "transparent";
            const gg = ctx.createLinearGradient(0, 0, W, 0);
            gg.addColorStop(0, MAGENTA);
            gg.addColorStop(1, PINK);
            ctx.fillStyle = gg;
            ctx.fillRect(0, by - bh / 2, W, 5 * k);
            ctx.fillRect(0, by + bh / 2 - 5 * k, W, 5 * k);
            ctx.restore();
            text(ctx, "FUNDED BY", W * 0.04, by, 22 * k, { color: INK, weight: 900, align: "left" });
            const fx0 = W * 0.2;
            const fstep = (W * 0.77) / FUNDERS.length;
            FUNDERS.forEach((f, j) => {
                const a = back(progress(m, 5.8 + j * 0.1, 6.3 + j * 0.1));
                if (a <= 0) return;
                const x = fx0 + fstep * (j + 0.5);
                scaled(ctx, x, by, Math.max(0, a), () => logo(ctx, f.id, x, by, fstep * 0.8, bh * 0.5, k, Math.min(1, a)));
            });
        }
    });
    //#endregion
};

const updateDom = (t: number) => {
    const next = sceneAt<Scene>(t, [
        ["intro", 0],
        ["map", T.map],
        ["team", T.team],
        ["decade", T.decade],
        ["domains", T.domains],
        ["how", T.how],
        ["partners", T.partners],
        ["outro", T.outro],
    ]);
    if (scene.value !== next) scene.value = next;
};

useCanvasTimeline(canvas, T.end, draw, { tick: updateDom, done: () => emit("done") });
</script>
<style scoped>
/* the player behind is dark navy; this showcase paints its own white backdrop */
.about {
    position: absolute;
    inset: 0;
    background: #fff;
}

/* the whole team is on the closing card: smaller faces that wrap */
.about :deep(.faces) {
    flex-wrap: wrap;
    justify-content: center;
    max-width: min(90vw, 70rem);
    row-gap: 0.6rem;
}

.about :deep(.faces img) {
    width: 3.6rem;
    height: 3.6rem;
    margin-right: -0.5rem;
}
</style>
